function kpisFullTable(items){return `<div class="table-scroll"><table><thead><tr><th>Código / indicador</th><th>Perspectiva</th><th>Objetivo asociado</th><th>Resultado actual</th><th>Meta</th><th>Cumplimiento</th><th>Frecuencia</th><th>Responsable</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${items.map(k=>`<tr><td><span class="code">${escapeHtml(k.id)}</span><span class="subcell">${escapeHtml(k.name)}</span></td><td>${escapeHtml(perspectiveLabel(k.perspective))}</td><td><span class="table-title">${escapeHtml(objectiveName(k.objectiveId))}</span></td><td><strong>${fmt(k.current,2)} ${escapeHtml(k.unit)}</strong></td><td>${fmt(k.target,2)} ${escapeHtml(k.unit)}</td><td>${achievement(k)===null?"—":fmt(achievement(k))+"%"}</td><td>${escapeHtml(k.frequency)}</td><td>${escapeHtml(k.owner)}</td><td>${statusBadge(k)}</td><td><div class="table-actions"><button class="text-action" data-action="kpi-detail" data-id="${k.id}">Detalle</button><button class="text-action" data-action="measure-kpi" data-id="${k.id}">Medir</button>${canEdit()?`<button class="text-action" data-action="edit-kpi" data-id="${k.id}">Editar</button><button class="text-action" data-action="delete-kpi" data-id="${k.id}">Eliminar</button>`:""}</div></td></tr>`).join("")||`<tr><td colspan="10"><div class="empty-state"><strong>No hay KPI</strong>Registra un indicador o cambia los filtros.</div></td></tr>`}</tbody></table></div><div class="table-bottom"><span>${items.length} indicador(es)</span><span>Los KPI sin medición se muestran como “Sin datos”.</span></div>`}
