function initiativesTable(items){return `<div class="table-scroll"><table><thead><tr><th>Iniciativa</th><th>Objetivo asociado</th><th>Responsable</th><th>Fechas</th><th>Presupuesto</th><th>Avance</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${items.map(i=>`<tr><td><span class="code">${escapeHtml(i.id)}</span><span class="subcell">${escapeHtml(i.name)}</span></td><td>${escapeHtml(objectiveName(i.objectiveId))}<span class="subcell">${escapeHtml(kpiName(i.kpiId))}</span></td><td>${escapeHtml(i.owner)}<span class="subcell">${escapeHtml(i.area)}</span></td><td>${escapeHtml(i.start)}<span class="subcell">hasta ${escapeHtml(i.end)}</span></td><td>${currency(i.budget)}</td><td><div class="initiative-progress"><div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,i.progress))}%;background:${i.progress===100?"#16845b":"#3478e5"}"></div></div><b>${fmt(i.progress,0)}%</b></div></td><td><span class="status ${i.status==="Finalizada"?"good":i.status==="En riesgo"?"bad":i.status==="Planificada"?"neutral":"blue"}">${escapeHtml(i.status)}</span></td><td><div class="table-actions"><button class="text-action" data-action="initiative-detail" data-id="${i.id}">Detalle</button>${canEdit()?`<button class="text-action" data-action="edit-initiative" data-id="${i.id}">Editar</button><button class="text-action" data-action="delete-initiative" data-id="${i.id}">Eliminar</button>`:""}</div></td></tr>`).join("")||`<tr><td colspan="8"><div class="empty-state"><strong>No hay iniciativas</strong>Crea una iniciativa para ejecutar un objetivo.</div></td></tr>`}</tbody></table></div><div class="table-bottom"><span>${items.length} iniciativa(s)</span><span>El avance se expresa en porcentaje de 0 a 100.</span></div>`}
