function chartAvailable(){return typeof window.Chart!=="undefined"}
function drawDashboardCharts(){
 if(!chartAvailable())return;
 const per=perspectiveBreakdown();
 const ctx=$("#perspectiveChart");if(ctx)charts.perspective=new Chart(ctx,{type:"bar",data:{labels:per.map(x=>x.label),datasets:[{label:"Cumplimiento (%)",data:per.map(x=>x.pct===null?0:x.pct),backgroundColor:per.map(x=>x.color),borderRadius:6,maxBarThickness:36}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:120,grid:{color:"#edf1f5"},ticks:{font:{size:10},callback:v=>v+"%"}},x:{grid:{display:false},ticks:{font:{size:9}}}}}});
 const ctx2=$("#trendChart");if(ctx2){
  const periods=trendPeriods();
  if(periods.length>=2){
   const values=periods.map(m=>{const vals=state.kpis.map(k=>{const mm=k.measurements.find(x=>x.period===m);return mm?achievement(k,mm.value):null}).filter(x=>x!==null);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null});
   charts.trend=new Chart(ctx2,{type:"line",data:{labels:periods,datasets:[{label:"Cumplimiento",data:values,borderColor:"#286de0",backgroundColor:"#286de01c",fill:true,tension:.35,pointRadius:3,pointBackgroundColor:"#286de0",spanGaps:true}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:120,grid:{color:"#edf1f5"},ticks:{font:{size:10},callback:v=>v+"%"}},x:{grid:{display:false},ticks:{font:{size:10}}}}}});
  }else{
   const rows=state.objectives.map(o=>({o,pct:weightedCompliance(state.kpis.filter(k=>k.objectiveId===o.id).map(k=>({pct:achievement(k),weight:k.weight})))}));
   const col=p=>p===null?"#94a3b8":p>=90?"#16845b":p>=75?"#d99a19":"#d23f49";
   charts.trend=new Chart(ctx2,{type:"bar",data:{labels:rows.map(r=>r.o.id+" · "+(r.o.name.length>26?r.o.name.slice(0,25)+"…":r.o.name)),datasets:[{label:"Cumplimiento (%)",data:rows.map(r=>r.pct===null?0:r.pct),backgroundColor:rows.map(r=>col(r.pct)),borderRadius:4,maxBarThickness:16}]},options:{indexAxis:"y",responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,max:120,grid:{color:"#edf1f5"},ticks:{font:{size:10},callback:v=>v+"%"}},y:{grid:{display:false},ticks:{font:{size:9}}}}}});
  }
 }
}
