 let existing=null;if(measureId){for(const x of state.kpis){existing=x.measurements.find(m=>m.id===measureId);if(existing)break}}
 const chosen=existing?state.kpis.find(x=>x.measurements.includes(existing)):k;
 const m=existing||{period:monthNow(),date:today(),value:"",notes:"",responsible:chosen.owner};
 const body=`<form id="measurementForm" class="detail-form-grid">${selectField("Indicador KPI","mKpi",state.kpis.map(x=>`<option value="${x.id}" ${x.id===chosen.id?"selected":""}>${escapeHtml(x.id+" · "+x.name)}</option>`).join(""))}${field("Período","mPeriod",m.period,"month",true)}${field("Fecha de medición","mDate",m.date,"date",true)}${field(`Valor obtenido (${escapeHtml(chosen.unit)})`,"mValue",m.value,"number",true,'step="any"')}${selectField("Responsable","mOwner",userOptions(m.responsible||chosen.owner))}<div class="field full-span"><label for="mNotes">Observaciones</label><textarea id="mNotes">${escapeHtml(m.notes)}</textarea></div><div class="field full-span"><div class="info-box">Al guardar, el sistema actualiza el valor actual del indicador si la medición corresponde al período más reciente o a un período posterior.</div></div></form>`;
 showModal(existing?"Editar medición":"Registrar resultado KPI",body,existing?"Guardar cambios":"Registrar medición",()=>{
  if(!validateForm(["mKpi","mPeriod","mDate","mValue","mOwner"]))return;
  const targetKpi=state.kpis.find(x=>x.id===$("#mKpi").value);const val=Number($("#mValue").value);if(!Number.isFinite(val)){toast("El resultado debe ser numérico.","error");return}
  const payload={period:$("#mPeriod").value,date:$("#mDate").value,value:val,notes:$("#mNotes").value.trim(),responsible:$("#mOwner").value};
  if(existing&&targetKpi===chosen){Object.assign(existing,payload)}else{if(existing){chosen.measurements=chosen.measurements.filter(x=>x.id!==existing.id)}const newid="M-"+targetKpi.id+"-"+Date.now();targetKpi.measurements.push({id:newid,...payload})}
  targetKpi.measurements.sort((a,b)=>a.period.localeCompare(b.period)||a.date.localeCompare(b.date));const latest=targetKpi.measurements[targetKpi.measurements.length-1];targetKpi.current=latest?.value??null;
  recordAudit(existing?"Edición":"Registro","Medición",`${targetKpi.id}: ${val} ${targetKpi.unit} (${payload.period})`);saveState();closeModal();renderPage(currentPage);toast(existing?"Medición actualizada":"Resultado registrado; dashboard y reportes actualizados");
 });
